#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using pll = pair<ll, ll>;

#define MAX 20000007
#define INF LLONG_MAX

ll n, x, y;
ll d[MAX];

ll sp() {
    set<pll> s;
    d[0] = 0;
    s.insert({0, 0});

    while (!s.empty()) {
        pll t = *s.begin();
        s.erase(s.begin());

        ll dist = t.first;
        ll u = t.second;

        if (u == n) return dist;

        if (u >= 2 && d[u - 1] > dist + x) {
            s.erase({d[u - 1], u - 1});
            d[u - 1] = dist + x;
            s.insert({d[u - 1], u - 1});
        }

        if (u < n && d[u + 1] > dist + x) {
            s.erase({d[u + 1], u + 1});
            d[u + 1] = dist + x;
            s.insert({d[u + 1], u + 1});
        }

        if (u < n && d[u * 2] > dist + y) {
            s.erase({d[u * 2], u * 2});
            d[u * 2] = dist + y;
            s.insert({d[u * 2], u * 2});
        }
    }

    return -1;
}

int main() {
    scanf("%lld %lld %lld", &n, &x, &y);
    fill(d, d + MAX, INF);
    printf("%lld\n", sp());
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, x, y;
    cin >> n >> x >> y;

    vector<ll> dp(n + 1);
    if (n >= 1) dp[1] = x;

    for (ll i = 2; i <= n; ++i) {
        dp[i] = dp[i - 1] + x;
        if (i % 2 == 0) {
            dp[i] = min(dp[i], dp[i / 2] + y);
        } else {
            dp[i] = min(dp[i], dp[(i + 1) / 2] + y + x);
        }
    }

    cout << dp[n] << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using pll = pair<ll, ll>;

int main() {
    ll n, x, y;
    scanf("%lld %lld %lld", &n, &x, &y);

    const ll INF = numeric_limits<ll>::max();
    vector<ll> dist(2 * n + 1, INF);
    priority_queue<pll, vector<pll>, greater<pll>> pq;

    dist[0] = 0;
    pq.push({0, 0});

    while (!pq.empty()) {
        auto [cost, u] = pq.top();
        pq.pop();

        if (cost != dist[u]) continue;
        if (u == n) {
            printf("%lld\n", cost);
            return 0;
        }

        auto relax = [&](ll v, ll weight) {
            if (cost <= INF - weight && dist[v] > cost + weight) {
                dist[v] = cost + weight;
                pq.push({dist[v], v});
            }
        };

        if (u > 0) relax(u - 1, x);
        if (u < n) {
            relax(u + 1, x);
            relax(u * 2, y);
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

ll n, x, y;
unordered_map<ll, i128> memo;

i128 solve(ll v) {
    if (v == 0) return 0;
    if (v == 1) return x;

    auto it = memo.find(v);
    if (it != memo.end()) return it->second;

    i128 ans = (i128)v * x;

    if (v % 2 == 0) {
        ans = min(ans, solve(v / 2) + y);
    } else {
        ans = min(ans, solve(v / 2) + y + x);
        ans = min(ans, solve(v / 2 + 1) + y + x);
    }

    return memo[v] = ans;
}

void printInt128(i128 value) {
    if (value == 0) {
        cout << '0';
        return;
    }
    string s;
    while (value > 0) {
        s.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> x >> y;
    printInt128(solve(n));
    cout << '\n';
    return 0;
}

